using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class CurveWitnessCheck {
 internal static int Run(string input,string output){var c=JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray().Single(r=>r!["fault"]!.GetValue<string>()=="control")!.AsObject();var root=c["root"]!.GetValue<string>();var a=c["args"]!.AsObject();var reply=c["result"]!.AsObject();_=CurveWitnessTools.ValidateReply(root,reply,a);int count=1;foreach(string fault in new[]{"source_sha","position","solid","typed_boolean"}){bool denied=false;try{var args=a.DeepClone().AsObject();var r=reply.DeepClone().AsObject();if(fault=="source_sha")args["inspectionSha256"]=new string('f',64);else if(fault=="position")r["curveWitnesses"]!["layout"]!["fields"]![0]!["values"]![0]=999;else if(fault=="solid")r["curveWitnesses"]!["solidSamples"]!["positions"]![0]!["value"]![0]=999;else r["curveControlsQualified"]="true";_=CurveWitnessTools.ValidateReply(root,r,args);}catch(ReferenceRejected){denied=true;}if(!denied)throw new InvalidDataException("Passive proof accepted forged "+fault);count++;}Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=count,["cadConnectionAttempted"]=false}.ToJsonString());Console.WriteLine($"PASS: {count} actual Framework passive curve/SOLID SDK proofs; no CAD.");return 0;}
}
